def ways_to_reach_position(start_pos,end_pos,k):
    from math import comb
    distance=abs(end_pos-start_pos)
    if distance>k or (k-distance)%2:return 0
    return comb(k,(k+end_pos-start_pos)//2)%(10**9+7)

